# -*- coding: utf-8 -*-
from conteudo_pts_a import PTS, pt

pt(cod="PT 402", titulo="Considerações de auditoria para entidade que usa organização prestadora de serviços", norma="NBC TA 402 (itens sobre entendimento dos serviços, relatórios tipo 1 e tipo 2, controles complementares da entidade usuária, procedimentos alternativos)",
 objetivo="Identificar serviços terceirizados relevantes e controles complementares; planejar análise de relatórios tipo 1/tipo 2 e procedimentos alternativos.",
 afirmacoes="Existência/valoração de aplicações financeiras, integridade de dívidas, exatidão de receitas de estacionamento e de sistemas de locação.",
 pop="Prestadores identificados em F1: gestores/administradores de fundos de investimento exclusivos (R$ 1.143.351 mil no consolidado, nota 7(i), F1 p.50); instituições financeiras emissoras de CDBs/letras (R$ 645.264 mil de CDBs); agentes fiduciários/escrituradores de debêntures e CRI (nota 13); meios de pagamento do estacionamento (liquidação em até 30 dias, F1 p.53); seguradoras (nota 26); sistemas de gestão de contratos e linearização (F1 p.11).",
 proc=[("RP","Identificar serviços relevantes e seu efeito nas DFs, conforme lista acima."),
       ("PL","Obter relatório tipo 2 (SOC 1) de custodiante/administrador dos fundos exclusivos e do provedor do sistema de contratos; avaliar período coberto, competência e independência do auditor do prestador e exceções."),
       ("PL","Mapear controles complementares da entidade usuária (CUECs): conciliações diárias de posições de fundos, aprovação de pagamentos, conciliação de estacionamento com adquirentes."),
       ("PL","Procedimentos alternativos se não houver relatório: confirmação direta de posições com administrador/custodiante (PT 505); inspeção de extratos; testes substantivos de detalhe."),
       ("RP","Registrar que nada em fonte pública menciona relatório SOC 1 da Allos (não é divulgado)." )],
 evid="F1 p.11, p.50, p.53, p.70-76; PT 330, PT 505.",
 res="Organizações relevantes identificadas; o risco maior é em aplicações financeiras (R$ 2,54 bi, 9,8% do ativo). A análise de relatórios é PLANEJADA; conclusão: não é possível afirmar a suficiência dos controles do prestador sem esses relatórios.")

pt(cod="PT 450", titulo="Avaliação das distorções identificadas durante a auditoria", norma="NBC TA 450 (itens sobre acúmulo de distorções, limites de claramente trivial, correção, avaliação de efeitos quantitativos e qualitativos)",
 objetivo="Mapa de distorções identificadas ou simuladas, corrigidas e não corrigidas, e avaliação dos efeitos quantitativos e qualitativos.",
 afirmacoes="Existência, corte, mensuração e classificação do PPI (SINTÉTICO).",
 pop="Registro de 1.040 erros inseridos (dados/registro_erros_inseridos.csv) x exceções dos testes (PT 330). Nenhuma distorção REAL na Allos foi identificada neste trabalho.",
 proc=[("SM","Acumular distorções por tipo (R$): duplicidade 22.927.175 (150); corte 10.090.343 (120); depreciação incorreta 134.594 (200); baixado com saldo 14.084.610 (80); VCL negativo 18.492.927 (60); terreno depreciado 23.071 (40); sem documento 43.733.663 (300, potencial de controle); manual atípico 64.325.618 (90, qualitativa)."),
       ("SM","Quantificadas monetárias (exclui 'sem documento' e 'manual atípico'): R$ 65.752.721 = 129% da materialidade global (R$ 50.880.050) e 172% da de execução."),
       ("SM","Triviais: limite R$ 2.544.002; maioria dos itens individuais é trivial, mas o acúmulo não é."),
       ("SM","Efeitos qualitativos: 90 lançamentos manuais atípicos (usuário fora do cadastro, fim de semana/31-12, valor redondo) indicam risco de burla de controles (NBC TA 240) e exigem investigação mesmo se pequenos."),
       ("SM","Correção: no cenário, o usuário solicitaria correção; distorções não corrigidas permanecem na simulação.")],
 evid="dados/resultados/mapa_distorcoes_PT450.csv; planilha aba PT450_Distorcoes; PT 240, PT 265, PT 530.",
 res="Simulado: o acúmulo de distorções excederia a materialidade; em auditoria real isso exigiria correção, ampliação de testes e, se persistisse, modificação da opinião. Limitação: são erros plantados, não achados reais.")

pt(cod="PT 500", titulo="Evidência de auditoria", norma="NBC TA 500 (itens sobre suficiência e adequação, relevância e confiabilidade, procedimentos de obtenção, informação da entidade)",
 objetivo="Avaliar relevância, confiabilidade e suficiência; reconciliar saldos com as DFs; explicitar limitações das fontes públicas e dos dados simulados.",
 afirmacoes="Todas as afirmações das contas citadas.",
 pop="F1 (DFs e notas auditadas) é a fonte primária; F2/F3 secundárias; W1-W5 de baixa confiabilidade.",
 proc=[("RP","Ranking de materialidade do ativo consolidado (R$ mil; % do total 26.006.439): PPI 20.381.666 (78,4%); aplicações financeiras 2.536.587 (9,8%); intangível 796.875 (3,1%); investimentos 604.106 (2,3%); contas a receber líquido 554.236 (2,1%). Conta escolhida para a base simulada: PPI."),
       ("RP","Reconciliações realizadas: ativo circulante 3.316.531 + não circulante 22.689.908 = 26.006.439; passivo 1.284.420 + 10.823.013 + PL 13.899.006 = 26.006.439; PPI do balanço = nota 11 (20.381.666); contas a receber 473.676 + 80.560 = nota 8 (554.236); aplicações 2.369.444 + 167.143 = nota 7 (2.536.587); dívidas 325.357 + 5.553.953 = 5.879.310 (nota 5); receita da nota 18 (soma por natureza menos deduções) = 2.859.106 = DRE; receita bruta da nota 18 = 3.069.454 = DVA; lucro 945.293 na DRE = DVA."),
       ("RP","Roll-forward do PPI (nota 11): 20.700.140 - 91.304 - 5.576 + 176.577 + 4.164 - 402.335 = 20.381.666 (diferença zero)."),
       ("RP","Rastreabilidade: o arquivo enviado como 'relatório do auditor' contém, na verdade, o comentário de desempenho, as DFs, as notas e o relatório da Deloitte (98 p.); o 'possível nota explicativa' é publicação legal resumida (Valor, 18/03/2026, 5 p.) e não substitui as notas de F1."),
       ("SM","Conciliação da base sintética: soma de R$ 20.448.164.979,64 = saldo DFP R$ 20.381.666.000,00 + R$ 66.498.979,59 de efeitos dos erros inseridos + resíduo de R$ 0,05 (arredondamento). Base antes dos erros = saldo DFP exato."),
       ("RP","Confiabilidade: F1 (demonstrações aprovadas e auditadas, alta); F2 (relatório e ITRs, média-alta); F3 (publicação, média); W (imprensa/analistas, baixa; usar só como indício).")],
 evid="planilha abas PT500_Conciliacao e PT320; F1 p.15-17, p.23, p.50-53, p.64-66, p.83; dados/resultados/resultados.json.",
 res="As DFs reconciliam internamente. Evidência é SUFICIENTE para conhecer os saldos reais e INSUFICIENTE para concluir sobre existência, direitos e valoração (sem inspeção, confirmação, acesso ao razão). Os dados simulados NÃO são evidência sobre a Allos. Limitação geral do trabalho.")

pt(cod="PT 501", titulo="Evidência de auditoria - itens específicos (estoques, litígios, segmentos)", norma="NBC TA 501 (itens sobre inventário, litígios e reivindicações, informações por segmento)",
 objetivo="Planejar procedimentos sobre estoques, litígios e segmentos; executar os permitidos pelas fontes.",
 afirmacoes="Estoques: existência/valoração; litígios: integridade e mensuração; segmentos: apresentação.",
 pop="Estoques: nenhuma rubrica de estoques no balanço (F1 p.15). Litígios: provisão R$ 254.628 mil e depósitos judiciais R$ 192.477 mil (F1 p.15-16, nota 14, p.74-77). Segmentos: nota 6 (F1 p.49).",
 proc=[("RP","ESTOQUES - análise: a atividade é locação, estacionamento e serviços; o balanço não tem estoques; terrenos destinados à negociação com incorporadores (R$ 70.566 mil) estão em PPI e não em estoques (nota 11(i), F1 p.64); materiais de consumo são despesa. Conclusão: contagem física não aplicável por ausência de estoques relevantes."),
       ("PL","Estoques: confirmar no razão que não há saldo material de materiais/mercadorias; verificar a classificação de eventuais terrenos para venda (CPC 16 x CPC 28) caso haja decisão de venda."),
       ("RP","LITÍGIOS - leitura: ações cíveis de indenização, rescisão, renovatórias e revisionais de aluguéis; controladas como rés e autoras (F1 p.77). Provisão 254.628 vs 241.548 em 2024 (+5,4%)."),
       ("PL","Litígios: carta aos assessores jurídicos (PT 505), lista de processos, análise de probabilidade; discussão com a administração; contingências possíveis."),
       ("RP","SEGMENTOS - recálculo: receita líquida de aluguel 1.952.114 + estacionamento 589.640 + outros 317.352 = 2.859.106 = DRE (diferença zero). Conclusão: segmentos reconciliam com a DRE.")],
 evid="F1 p.15-16, p.49, p.64, p.74-77; PT 250, PT 505.",
 res="Segmentos reconciliados; litígios e estoques tratados com a análise possível. Limitação: sem lista de processos e sem confirmação jurídica.")

pt(cod="PT 505", titulo="Confirmações externas", norma="NBC TA 505 (itens sobre procedimentos, resposta da parte, não resposta, exceções e procedimentos alternativos)",
 objetivo="Preparar modelos, controle de circularização, tratamento de diferenças e procedimentos alternativos; NÃO enviar solicitações.",
 afirmacoes="Existência e direitos de aplicações; integridade de dívidas; existência/valoração de recebíveis; integridade de contingências.",
 pop="Itens a circularizar (saldos em 31/12/2025, R$ mil): aplicações 2.536.587; dívidas 5.879.310; contas a receber bruto 1.006.629; contingências via advogados 254.628; partes relacionadas 55.865 (ativo)/7.361 (passivo).",
 proc=[("SM","MODELO BANCOS (NÃO ENVIADO): 'Solicitamos informar, em 31/12/2025, saldos, posições, taxas, vencimentos, garantias e restrições das operações da ALLOS S.A. com essa instituição.' Resposta direta ao auditor."),
       ("SM","MODELO DEBENTURISTAS/AGENTE FIDUCIÁRIO e CRI: saldo, juros, covenants e eventos de vencimento antecipado."),
       ("SM","MODELO CLIENTES (positiva, grandes lojistas): saldo a receber por contrato e vencimentos."),
       ("SM","MODELO ADVOGADOS: processos, probabilidade de perda, valores e depósitos."),
       ("PL","Controle de circularização: planilha (item, valor, data de envio, data de resposta, diferença, tratamento); reenvio em não resposta; diferenças tratadas como conciliação (timing, erro, disputa) e distorções (PT 450)."),
       ("PL","Alternativos: extratos, liquidações posteriores, contratos, notas de débito, conferência de depósitos.")],
 evid="F1 p.15-16, p.49-53, p.70-77, p.85; PT 330, PT 402, PT 550.",
 res="NENHUMA solicitação real foi enviada, em cumprimento à regra do trabalho. Estrutura pronta para uso numa auditoria real. Limitação: não há respostas nem testes de diferença.")

pt(cod="PT 510", titulo="Trabalho inicial - saldos de abertura", norma="NBC TA 510 (itens sobre saldos de abertura, políticas contábeis consistentes, relatório do auditor anterior)",
 objetivo="Tratar o caso como auditoria inicial didática: examinar saldos de abertura, políticas contábeis e efeitos de modificação na opinião do auditor anterior.",
 afirmacoes="Existência, integridade e mensuração dos saldos de 31/12/2024; consistência das políticas.",
 pop="Saldos 31/12/2024 em F1 (colunas comparativas, p.15-16) e no balanço de 30/06/2025 de F2 (coluna 31/12/2024, p.76-77).",
 proc=[("RP","Teste de consistência entre fontes independentes: caixa 47.771; aplicações circulantes 3.321.334; contas a receber circulante 492.367; PPI 20.700.140; imobilizado 97.391; intangível 826.970; empréstimos circulante 1.123.404 e não circulante 5.521.620; PL 14.134.520; TOTAL ATIVO 27.288.790 - iguais em F1 e em F2. Diferenças: zero nas rubricas conferidas."),
       ("RP","Políticas contábeis: o relatório de 2025 não aponta mudança de política; DRE/DFC do comparativo 2024 em F1 p.17, p.22."),
       ("PL","Obter DFs e relatório do auditor anterior de 2024 (não incluídos nos documentos enviados), papéis de trabalho do antecessor, procedimentos sobre saldos que afetam 2025 (PPI, dívidas, PCE) e investigação de qualquer modificação de opinião."),
       ("SM","Simulação de auditoria inicial: tratar PPI de abertura como saldo de abertura crítico; o roll-forward da nota 11 liga 20.700.140 a 20.381.666 sem diferença.")],
 evid="F1 p.15-17, p.22, p.65-66; F2 p.76-77; PT 500.",
 res="Consistência dos saldos de abertura verificada em nível agregado com fontes públicas. Não é possível concluir sobre a opinião do auditor anterior nem sobre o trabalho do antecessor (PLANEJADO). Limitação: auditor de 2024 não identificado nas fontes enviadas.")

pt(cod="PT 520", titulo="Procedimentos analíticos", norma="NBC TA 520 (itens sobre procedimentos analíticos substantivos e na revisão final; expectativas, limiares, investigação)",
 objetivo="Construir expectativas, definir precisão e limite de investigação, calcular relações e variações e investigar diferenças.",
 afirmacoes="Ocorrência, integridade e mensuração de receitas e saldos patrimoniais.",
 pop="DFP 2025 e comparativos 2024, consolidado (planilha PT520_Analiticos, 18 linhas). Limite de investigação: materialidade de execução R$ 38.160 mil.",
 proc=[("RP","Expectativa de receitas: 2024 x (1 + 4%) [premissa didática do aluno - substituir por IPCA/IGP-M oficial]. Receita líquida real 2.859.106 vs esperada 2.849.442 (dif. +9.664, abaixo do limite): consistente. Aluguéis +3.356; estacionamento +12.572; serviços -1.603; custo -802: todos abaixo do limite."),
       ("RP","Investigação das variações acima do limite: (i) LAIR +149.420 = lucro operacional +86.256 e resultado financeiro +63.164 (despesas financeiras -37.440; receitas financeiras +25.724), reconcilia; (ii) PPI -318.474 = baixas 402.335 vs adições líquidas 83.861 (nota 11), diferença zero; (iii) aplicações financeiras -974.798 e dívidas -765.714: pagamentos de obrigações de aquisições 450.122, dividendos 708.000, principal de dívidas e debêntures de 859.818 e 582.196 contra emissão de 625.000 (DFC, F1 p.22); (iv) obrigações por compra de ativos -409.349: liquidação do saldo devido por 50% do Espírito Santo Mall (373.013) e Mídia Malls (30.605) (nota 15.1); (v) dividendos a pagar +229.041: R$ 438.000 mil declarados na controladora (balanço); (vi) despesas gerais e administrativas -11.715, diferença de -39.884 vs expectativa de +4%: queda de 'outras despesas' (-10.492) e legais/tributárias (-4.774) (nota 20); sinergias capturadas de R$ 184 mi (W1) sustentam em parte, PL confirmação com o razão."),
       ("SM","Analítico na base sintética: depreciação do exercício somada = R$ 247.566.771 vs recalculada R$ 249.091.161 (+0,6%, efeito dos erros) e vs R$ 459.233.000 da nota 19 (54%): a base foi calibrada nos SALDOS, não na despesa; a diferença é limitação de calibração, não achado."),
       ("RP","Revisão final (analítico global): resultados e saldos coerentes entre si e com PAAs do auditor real.")],
 evid="planilha PT520_Analiticos; F1 p.17, p.22, p.64-66, p.77, p.83; dados/resultados/resultados.json.",
 res="Variações acima do limite foram explicadas com documentos públicos, exceto o detalhe das despesas gerais, que é PLANEJADO (razão). Cálculos reproduzíveis na planilha (fórmulas vivas). Limitação: expectativa de 4% é premissa e deve ser substituída por índice oficial.")

pt(cod="PT 530", titulo="Amostragem de auditoria", norma="NBC TA 530 (itens sobre desenho da amostra, tamanho, seleção, desempenho dos procedimentos, distorções, projeção, avaliação)",
 objetivo="Aplicar amostragem à base simulada: população, unidade amostral, método, tamanho, seleção, risco, tratamento e projeção de erros.",
 afirmacoes="Existência/ocorrência, corte, mensuração do PPI (SINTÉTICO).",
 pop="Base sintética de 520.150 registros, VCL de R$ 20.448.164.979,64. Unidade amostral: o real (unidade monetária). Itens-chave (>= erro tolerável R$ 38.160.037,50): 4, VCL R$ 288.114.244 - 100%. Negativos: 60 - 100%. MUS: R$ 20.161.940.003.",
 proc=[("SM","Método: MUS (amostragem por unidade monetária), seleção sistemática com início aleatório (semente = matrícula 231004987; início R$ 1.588.883,60)."),
       ("SM","Parâmetros: confiança 95%; fator Poisson RF=3,00 (erro esperado zero); erro tolerável = materialidade de execução; intervalo = 38.160.037,50/3 = R$ 12.720.012,50; n calculado 1.586; selecionados 1.570 (itens maiores que o intervalo são atingidos mais de uma vez)."),
       ("SM","Desempenho: cada item foi submetido ao procedimento de inspeção simulada (documento, data, status, recálculo de depreciação, classificação). 18 itens com exceção; 10 com distorção monetária quantificada: R$ 3.040.314."),
       ("SM","Projeção: taint total x intervalo = R$ 39.488.929; precisão básica R$ 38.160.038; limite superior (Stringer, incrementos Poisson 95%) = R$ 100.530.747 > erro tolerável R$ 38.160.038."),
       ("SM","Comparação com o registro: 8 tipos de erro inseridos; a amostra capturou poucos (duplicidade 1; baixado 2; sem documento 6; manual atípico 9) porque a população de erros é pequena frente a 520 mil itens; a população inteira (CAAT) detectou 100%.")],
 evid="dados/resultados/amostra_mus_selecionada.csv; itens_chave_100pct.csv; comparacao_erros_inseridos_x_amostra.csv; planilha PT530_Amostragem.",
 res="O limite superior excede o erro tolerável: a população NÃO é aceita sem ampliação de testes e ajuste. Observação: o CAAT em 100% dos registros é a resposta eficiente; a amostra serve para testes que exigem inspeção de documentos. Limitação: a inspeção é simulada por regras sobre atributos da própria base.")

pt(cod="PT 540", titulo="Auditoria de estimativas contábeis e divulgações", norma="NBC TA 540 (itens sobre métodos, premissas, dados, incerteza de estimativa, viés da administração, análise de sensibilidade)",
 objetivo="Selecionar estimativa relevante; avaliar método, premissas, dados, incerteza e viés; executar sensibilidade.",
 afirmacoes="Mensuração e divulgação da PCE e do valor recuperável de PPI.",
 pop="Estimativa 1: PCE (R$ 546.430 mil; nota 8, F1 p.50-53). Estimativa 2: valor recuperável do PPI com valor justo divulgado de R$ 32.208.683 mil (nota 11, F1 p.66).",
 proc=[("RP","Estimativa 1 - método: matriz de perdas por faixa de atraso (a vencer 3,78%; até 90 dias 39,52%; 91-180 65,79%; 181-360 91,01%; >360 100%) para aluguéis, CDU e cotas; análise individual para serviços e outros; estacionamento sem provisão."),
       ("RP","Recálculo pela matriz sobre aluguéis+CDU+cotas: R$ 497.805 mil vs PCE total registrada R$ 546.430 mil; diferença R$ 48.625 mil (1,27x a materialidade de execução)."),
       ("RP","Explicação (proxy): aplicando a mesma matriz aos saldos de serviços e outros (R$ 96.904 mil bruto; R$ 40.786 mil acima de 360 dias), a provisão esperada é R$ 52.426 mil; resíduo de R$ 3.801 mil (< limite). A diferença é plausível, mas a análise individual real é PL."),
       ("RP","Variação vs 2024: PCE 519.209 -> 546.430 (+5,2%); saldo bruto 1.002.144 -> 1.006.629 (+0,4%); cobertura aumenta (51,8% -> 54,3%). Ponto de atenção para viés: despesa de PCE de R$ 47.458 mil em 2025 vs 49.074."),
       ("SM","Sensibilidade (planilha PT540): +/-5 p.p. nas faixas vencidas = +/-R$ 3.423 mil; +/-10 p.p. = -6.847/+6.535 mil (0,17-0,18x a materialidade de execução): baixa sensibilidade."),
       ("SM","Estimativa 2 (indicativo estilizado, NÃO é avaliação): taxas de desconto divulgadas 7,25%-11,75% (ponto médio 9,5%). Com valor presente proporcional a 1/r, +100 bps reduzem o valor justo de 32,21 bi para ~29,14 bi e +200 bps para ~26,61 bi; ambos acima do valor contábil de 20,38 bi. Ressalva: o valor justo inclui minoritários (F1 p.66) e o contábil é consolidado a 100% dos controlados; comparação apenas indicativa."),
       ("PL","Testar dados e premissas do modelo interno de fluxo de caixa; especialista; comparar projeções passadas com realizado; avaliar viés.")],
 evid="planilha PT540_PCE; F1 p.50-53, p.66; PT 330, PT 500.",
 res="Estimativa 1: razoável por recálculo e proxy; Estimativa 2: o sinal de folga é grande, mas só uma avaliação independente com dados internos conclui. Sinal de viés: nenhum identificado em dados públicos. Limitação: sem acesso ao modelo e aos dados.")

pt(cod="PT 550", titulo="Partes relacionadas", norma="NBC TA 550 (itens sobre identificação, riscos, procedimentos sobre transações não usuais, avaliação de divulgação, representações)",
 objetivo="Mapear vínculos, saldos e transações; avaliar completude e divulgação; planejar identificação de operações não informadas.",
 afirmacoes="Integridade, apresentação e divulgação.",
 pop="Nota 23 (F1 p.85) e nota 10 (investimentos, F1 p.55-63).",
 proc=[("RP","Saldos consolidados (R$ mil, 31/12/2025): ativo não circulante 55.865 = Ricardo Rique 264 + Reinaldo Rique 12.990 + Parque D. Pedro 1 BV 42.611; passivo não circulante 7.361 = Luciana Rique 154 + FIP Bali/RLB 7.207 (soma conferida). CPPIB US RE-A: 62.759 de passivo em 2024 e zero em 2025."),
       ("RP","Controladora: receitas de administração e serviços cobradas de controladas/coligadas R$ 12.821 mil (2024: R$ 8.839 mil); debêntures de R$ 400.000 mil a favor de EDRJ113 Participações (CDI + 0,95%; R$ 53.390 em 08/10/2024 e R$ 346.610 em 08/10/2025)."),
       ("RP","Dividendos a receber de controladas: R$ 72.603 mil na controladora (nota 10f, F1 p.64)."),
       ("PL","Completude: cruzar cadastro de sócios, administradores e partes ligadas com razão de fornecedores/clientes; revisar atas; indagar a administração e a governança; testar transações incomuns (fora do curso normal)."),
       ("SM","Registro dos 90 lançamentos manuais atípicos da base como indicador a investigar quanto a partes relacionadas.")],
 evid="F1 p.55-64, p.85; PT 505, PT 580.",
 res="Mapa elaborado e saldos reconciliados internamente. Não é possível concluir sobre completude (PLANEJADO). Limitação: lista oficial de partes relacionadas é interna.")

pt(cod="PT 560", titulo="Eventos subsequentes", norma="NBC TA 560 (itens sobre eventos até a data do relatório, fatos descobertos depois, ajuste x divulgação)",
 objetivo="Fixar data de corte da pesquisa; examinar publicações posteriores ao encerramento; distinguir eventos que exigem ajuste dos que exigem divulgação.",
 afirmacoes="Corte, apresentação e divulgação.",
 pop="Data do balanço: 31/12/2025. Data do relatório do auditor real: 10/03/2026 (F1 p.14). DATA DE CORTE DA PESQUISA DESTE TRABALHO: 20/10/2026.",
 proc=[("RP","Evento 1: incêndio no Shopping Tijuca em 02/01/2026 (comunicado de 04/01/2026, W2): interrupção total por 14 dias, reabertura em 16/01/2026, estimativas de perdas em avaliação e cobertura de seguros (nota 28, F1 p.92). Natureza: evento NÃO ajustável (condição surgiu após 31/12/2025) -> divulgação, que ocorreu. Teste: confirmar se há indício de impairment em 31/12/2025 - não, pois o evento é posterior."),
       ("RP","Evento 2: assinatura em 10/03/2026 da 9ª emissão de debêntures (R$ 1.000.000 mil, podendo aumentar até 25%) (nota 28): não ajustável; divulgação feita."),
       ("RP","Posteriores ao relatório (10/03/2026), apenas informativos, de fontes secundárias: resultados do 1T26 com impacto de Tijuca (W5) e do 2T26 (W4); expectativa de Kinea ALLOS Malls FII (MOU, R$ 790 mi a R$ 1,97 bi, até 7 ativos) (W3). Nenhum indica fato que existisse em 31/12/2025."),
       ("PL","Procedimentos reais: ler atas e demonstrações intermediárias posteriores, indagar sobre litígios e seguros, avaliar perdas do Tijuca e recuperação de seguros; carta de representações atualizada até a data do relatório.")],
 evid="F1 p.14, p.92; W2-W5; PT 250, PT 570, PT 580.",
 res="Dois eventos subsequentes identificados, ambos de divulgação. Sem ajuste exigido por informação pública. Limitação: ampliação do impacto do Tijuca (perdas líquidas de seguro) é desconhecida na data-base.")

